				context->pass++;
				context->curY = i->posY + 2;
			}
 			break;
 		case 3:	/* 3rd pass : every fourth row starting from 2 */
 			context->curY += 4;
			if(context->curY >= p->height) {
				context->pass++;
				context->curY = i->posY + 1;
			}
 			break;
 		case 4:	/* 4th pass : every odd row */
 			context->curY += 2;
